string[] words = { "cat", "car", "dog", "door", "ant" };
var res = words.GroupBy(w => w[0])
               .Where(g => g.Count() > 1)
               .Select(g => $"{g.Key}:{g.Count()}");
Console.WriteLine(string.Join(" ", res));

int[] data = { 10, 20, 30, 40, 50 };
int total = data.Skip(1).Take(3).Aggregate(0, (acc, x) => acc + x);
Console.WriteLine(total);

var groups = new[] { new[] { 1, 2 }, new[] { 2, 3, 1 } };
